## Implementace v FA (Delphi)

FA musí při otevření Cursoru:

1. **Zjistit svůj PID:**
```pascal
function GetFAProcessId: Integer;
begin
  Result := GetCurrentProcessId;
end;
```

2. **Zapsat do `.fsbridge/fa_instance.txt`:**
```pascal
procedure WriteFAInstanceId(const WorkspacePath: string);
var
  InstanceFile: string;
  PID: Integer;
  SL: TStringList;
begin
  PID := GetCurrentProcessId;
  InstanceFile := IncludeTrailingPathDelimiter(WorkspacePath) + '.fsbridge\fa_instance.txt';
  // Zajisti existenci složky
  EnsureDir(ExtractFilePath(InstanceFile));
  // Zapiš PID jako text
  SL := TStringList.Create;
  try
    SL.Text := IntToStr(PID);
    SL.SaveToFile(InstanceFile);
  finally
    SL.Free;
  end;
end;
```

3. **Používat instance-specific cesty:**
```pascal
function GetCommandFilePath: string;
var
  InstanceId: string;
begin
  InstanceId := ReadFAInstanceId; // Načti z fa_instance.txt
  if InstanceId <> '' then
    Result := IncludeTrailingPathDelimiter(EffectiveExportFolder)
            + '.fsbridge' + PathDelim
            + 'facmd_' + InstanceId + '.txt'
  else
    Result := IncludeTrailingPathDelimiter(EffectiveExportFolder)
            + '.fsbridge' + PathDelim
            + 'facmd.txt';
end;
```

4. **Kontrola existence okna Cursoru před použitím `-r` parametru:**

**Problém:** Parametr `-r` (reuse) vždy reusuje existující okno. Pokud není žádné okno otevřené, mělo by se otevřít nové okno bez `-r`.

**Řešení:** Upravit `RunCursorReuse()` tak, aby před použitím `-r` zkontrolovala, jestli existuje okno Cursoru/VS Code.

```pascal
function TCursorBridge.RunCursorReuse(const AFolder, AFile: string; ALine, ACol: Integer): Boolean;
var
  Params, FolderArg, FileArg, WS, Cmd: string;
  Ext: string;
  H: HWND;
  Preferred: string;
  UseReuse: Boolean;
begin
  // Workspace = EffectiveExportFolder, soubor otevřít přes -g (řádek[:sloupec])
  WS := EffectiveExportFolder;
  FolderArg := '"' + WS + '"';

  if (ALine > 0) and (ACol > 0) then
    FileArg := Format(' -g "%s:%d:%d"', [AFile, ALine, ACol])
  else if (ALine > 0) then
    FileArg := Format(' -g "%s:%d"', [AFile, ALine])
  else
    FileArg := Format(' "%s"', [AFile]);

  // Zkontroluj, jestli už existuje okno Cursoru/VS Code
  Preferred := BaseName(FCursorCmdOrPath);
  UseReuse := False;
  
  if Pos('CODE', Preferred) > 0 then
  begin
    H := FindMainWindowOfProcess('Code.exe');
    if H = 0 then H := FindMainWindowOfProcess('Cursor.exe');
  end
  else
  begin
    H := FindMainWindowOfProcess('Cursor.exe');
    if H = 0 then H := FindMainWindowOfProcess('Code.exe');
  end;
  
  UseReuse := (H <> 0);

  // Pořadí: nejdřív workspace (složka), potom soubor
  // Použij -r pouze pokud už existuje okno, jinak otevři nové
  if UseReuse then
    Params := Format('-r %s%s', [FolderArg, FileArg])
  else
    Params := Format('%s%s', [FolderArg, FileArg]);

  // Najdi skutečný spustitelný soubor (EXE), případně CMD na PATH
  Cmd := ResolveEditorCommand;
  Ext := LowerCase(ExtractFileExt(Cmd));

  if (Ext = '.cmd') or (Ext = '.bat') then
  begin
    // Spusť .cmd/.bat bez blikající konzole (okno editoru se otevře normálně)
    Result := ShellExecNoConsole(Cmd, Params, WS, SW_HIDE);
  end
  else
  begin
    // EXE – běžné spuštění bez mezikroku v cmd.exe
    Result := ShellExecNoConsole(Cmd, Params, WS, SW_SHOWNORMAL);
  end;
end;
```

**Poznámka:** Kontrola existence okna je obecná (zkontroluje jakékoli okno Cursoru/VS Code). Při více instancích FA může být více oken Cursoru, ale Cursor automaticky otevře správné okno podle workspace. Pokud okno neexistuje, otevře se nové.

**Výhody:**
- ✅ Pokud není otevřené žádné okno Cursoru → otevře se nové okno
- ✅ Pokud už je otevřené okno Cursoru → použije se existující okno (reuse)
- ✅ Funguje i při více instancích FA (Cursor automaticky správně směruje podle workspace)

## Cleanup starých souborů (volitelné)

